const body = $('Webhook').first().json.body;
const raw = $input.first().json.text ?? $input.first().json.output ?? '';
const questions = [];
for (const blk of raw.split(/\n\s*\n/)) {
  const q = blk.match(/Soru:\s*(.+)/);
  const opts = ['A', 'B', 'C', 'D'].map(l => {
    const m = blk.match(new RegExp('^\\s*' + l + '\\)\\s*(.+)$', 'm'));
    return m ? m[1].trim() : null;
  });
  const ans = blk.match(/Cevap:\s*\(?([ABCD])/i);
  const exp = blk.match(/A[çc]ıklama:\s*(.+)/i);
  if (!q || opts.some(o => !o) || !ans) continue;
  if (new Set(opts.map(o => o.toLowerCase())).size < 4) continue;
  const correctIdx = 'ABCD'.indexOf(ans[1].toUpperCase());
  let options = opts.map((text, i) => ({ text, correct: i === correctIdx }));
  for (let i = options.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [options[i], options[j]] = [options[j], options[i]];
  }
  questions.push({
    question_text: q[1].trim(),
    options: options.map(o => o.text),
    correct_index: options.findIndex(o => o.correct),
    explanation: exp ? exp[1].trim() : null
  });
}
const n = Number(body.question_count) || 5;
return [{ json: { job_id: body.job_id, questions: questions.slice(0, n), model: 'gemma3:4b' } }];
